import { ItemInfo } from "../../components/ItemInfo.js";
import { NamedIdentity } from "../../components/NamedIdentity.js";
import { inventoryItems, inventoryContains } from "../../utils/inventoryFacade.js";
import { Equipment, GEAR_SLOTS } from "../../components/Equipment.js";
import { getItemHooksByIdentity } from "./itemHooks.js";
import { Beatitude } from "../../components/Beatitude.js";
import { Material } from "../../components/Material.js";

/**
 * @typedef {{
 *   actor: number,
 *   toolId: number,
 *   targetId: number,
 *   toolIdentity: string,
 *   targetIdentity: string,
 *   toolInfo: any,
 *   targetInfo: any,
 * }} ApplyPayloadState
 */

/**
 * @typedef {{
 *   id: string,
 *   matches: (state: ApplyPayloadState) => boolean,
 *   beforeApply?: (ctx: any, state: ApplyPayloadState) => unknown,
 *   onApply?: (ctx: any, state: ApplyPayloadState) => unknown,
 *   afterApply?: (ctx: any, state: ApplyPayloadState) => unknown,
 * }} ApplyPayloadDef
 */

/**
 * Reserved for cross-item matcher payloads only.
 * Item-specific apply behavior should live on item-def hooks.
 * @type {ApplyPayloadDef[]}
 */
export const APPLY_PAYLOADS = Object.freeze([]);

/**
 * @param {{
 *   identity: (entityId: number) => string,
 *   itemInfo: (entityId: number) => any,
 * }} reader
 * @param {{ actor: number, toolId: number, targetId: number }} spec
 * @returns {ApplyPayloadState}
 */
export function buildApplyPayloadState(reader, spec) {
  const actor = spec?.actor | 0;
  const toolId = spec?.toolId | 0;
  const targetId = spec?.targetId | 0;
  return {
    actor,
    toolId,
    targetId,
    toolIdentity: String(reader?.identity?.(toolId) || "").toLowerCase(),
    targetIdentity: String(reader?.identity?.(targetId) || "").toLowerCase(),
    toolInfo: reader?.itemInfo?.(toolId),
    targetInfo: reader?.itemInfo?.(targetId),
    targetBeatitude: String(reader?.beatitude?.(targetId) || ""),
    actorEquipment: reader?.equipment?.(actor),
    weaponInfo: reader?.itemInfo?.(Number(reader?.equipment?.(actor)?.weapon || 0) | 0),
    weaponMaterial: String(reader?.material?.(Number(reader?.equipment?.(actor)?.weapon || 0) | 0) || ""),
  };
}

/**
 * @param {ApplyPayloadState} state
 * @returns {ApplyPayloadDef | null}
 */
export function findApplyPayload(state) {
  const hooks = getItemHooksByIdentity(state?.toolIdentity || "");
  if (typeof hooks.onDip !== "function") return null;

  if (typeof hooks.canDipTarget === "function") {
    try {
      if (!hooks.canDipTarget(state)) return null;
    } catch {
      return null;
    }
  }

  return {
    id: `item:${String(state?.toolIdentity || "unknown")}:onDip`,
    matches: () => true,
    beforeApply: typeof hooks.beforeDip === "function"
      ? (ctx, nextState) => hooks.beforeDip(ctx, nextState)
      : undefined,
    onApply: (ctx, nextState) => hooks.onDip(ctx, nextState),
    afterApply: typeof hooks.afterDip === "function"
      ? (ctx, nextState) => hooks.afterDip(ctx, nextState)
      : undefined,
  };
}

/**
 * Resolve the canonical apply payload for a tool/target pair from any reader.
 * Shared by runtime pipeline and UI targetability helpers.
 *
 * @param {{
 *   identity: (entityId: number) => string,
 *   itemInfo: (entityId: number) => any,
 * }} reader
 * @param {{ actor: number, toolId: number, targetId: number }} spec
 * @returns {{ state: ApplyPayloadState, payloadDef: ApplyPayloadDef | null }}
 */
export function resolveApplyPayload(reader, spec) {
  const state = buildApplyPayloadState(reader, spec);
  const payloadDef = findApplyPayload(state);
  return { state, payloadDef };
}

/**
 * @param {import("../../../lib/ecs-js/index.js").World} world
 */
function createWorldApplyPayloadReader(world) {
  return {
    identity(entityId) {
      const ni = /** @type any */ (world.get(entityId | 0, NamedIdentity));
      return String(ni?.identity || "");
    },
    itemInfo(entityId) {
      return /** @type any */ (world.get(entityId | 0, ItemInfo));
    },
    beatitude(entityId) {
      return /** @type any */ (world.get(entityId | 0, Beatitude))?.state || '';
    },
    equipment(entityId) {
      return /** @type any */ (world.get(entityId | 0, Equipment));
    },
    material(entityId) {
      return /** @type any */ (world.get(entityId | 0, Material))?.kind || "";
    },
  };
}

/**
 * World-backed resolver wrapper for apply payload lookup.
 * @param {import("../../../lib/ecs-js/index.js").World} world
 * @param {{ actor: number, toolId: number, targetId: number }} spec
 */
export function resolveApplyPayloadForWorld(world, spec) {
  const reader = createWorldApplyPayloadReader(world);
  return resolveApplyPayload(reader, spec);
}

/**
 * @param {import("../../../lib/ecs-js/index.js").World} world
 * @param {number} actor
 * @param {number} toolId
 */
export function listApplyTargetsForTool(world, actor, toolId) {
  const actorId = actor | 0;
  const toolEntityId = toolId | 0;
  if (!world || !(actorId > 0) || !(toolEntityId > 0)) return [];
  if (!world.isAlive(actorId) || !world.isAlive(toolEntityId)) return [];

  if (!inventoryContains(world, actorId, toolEntityId)) return [];

  const items = inventoryItems(world, actorId);

  // Also include equipped items as potential targets (e.g. socketing gems into equipped weapons)
  const eq = world.get(actorId, Equipment);
  const seen = new Set(items);
  if (eq) {
    for (let s = 0; s < GEAR_SLOTS.length; s++) {
      const eqId = eq[GEAR_SLOTS[s]] | 0;
      if (eqId > 0 && !seen.has(eqId)) { seen.add(eqId); items.push(eqId); }
    }
  }

  const out = [];
  const reader = createWorldApplyPayloadReader(world);
  for (let i = 0; i < items.length; i++) {
    const targetId = items[i] | 0;
    if (!(targetId > 0) || targetId === toolEntityId) continue;
    if (!world.isAlive(targetId)) continue;

    const { payloadDef } = resolveApplyPayload(reader, {
      actor: actorId,
      toolId: toolEntityId,
      targetId,
    });
    if (payloadDef) out.push(targetId);
  }
  return out;
}

/**
 * @param {import("../../../lib/ecs-js/index.js").World} world
 * @param {number} actor
 * @param {number} toolId
 */
export function canUseApplyTool(world, actor, toolId) {
  return listApplyTargetsForTool(world, actor, toolId).length > 0;
}

/**
 * Returns true if an inventory item is an apply-capable tool, even when there
 * are currently no valid targets.
 *
 * @param {import("../../../lib/ecs-js/index.js").World} world
 * @param {number} actor
 * @param {number} toolId
 */
export function isApplyTool(world, actor, toolId) {
  const actorId = actor | 0;
  const toolEntityId = toolId | 0;
  if (!world || !(actorId > 0) || !(toolEntityId > 0)) return false;
  if (!world.isAlive(actorId) || !world.isAlive(toolEntityId)) return false;

  if (!inventoryContains(world, actorId, toolEntityId)) return false;

  const reader = createWorldApplyPayloadReader(world);
  const state = buildApplyPayloadState(reader, {
    actor: actorId,
    toolId: toolEntityId,
    targetId: 0,
  });
  const hooks = getItemHooksByIdentity(state.toolIdentity);
  if (typeof hooks.onDip === "function") return true;

  return listApplyTargetsForTool(world, actorId, toolEntityId).length > 0;
}
  if (!targetInfo || String(targetInfo.type || '') !== 'equip') return false;
  const slot = normalizeEnchantSlot(targetInfo.slot);
  if (!slot || slot === 'ammo') return false;
  const scrollDef = getEnchantScrollDef(state?.toolIdentity || state?.toolId || '');
  const runtimeAffixId = scrollDef?.runtime?.affixId || scrollDef?.affixId;
  if (!runtimeAffixId) return false;
  return enchantDefSupportsSlot(scrollDef, slot) && affixSupportsSlot(runtimeAffixId, slot);
}

function createEnchantScrollUseHint(message) {
  const text = String(message || 'Choose a piece of gear to enchant.');
  return () => ({ consumed: false, cancelled: true, code: 'USE_ENCHANT_SCROLL_TARGET', message: text, consumesTurn: false });
}

function createGearEnchantDipHook({ affixId, enchantType, enchantLabel, detail, allowedSlots, magnitude, proc, duration, metadata }) {
  const resolvedAffixId = String(affixId || '').trim();
  const resolvedType = String(enchantType || '').trim().toLowerCase();
  const resolvedLabel = String(enchantLabel || resolvedType || 'enchant');
  const resolvedDetail = String(detail || '');
  const scrollDef = { affixId: resolvedAffixId, allowedSlots: Array.isArray(allowedSlots) ? allowedSlots.slice() : [] };
  return (ctx, state) => {
    const targetId = Number(state?.targetId || 0) | 0;
    if (!(targetId > 0)) { ctx.cancel({ code: 'ENCHANT_INVALID_TARGET', message: 'That scroll needs a piece of gear to bind to.', consumesTurn: false }); return { applied: false, consumedTool: false, resultType: 'nothing' }; }
    const info = ctx.query.itemInfo(targetId);
    if (!info || String(info.type || '') !== 'equip') { ctx.cancel({ code: 'ENCHANT_INVALID_TARGET', message: 'Only gear can hold that enchantment.', consumesTurn: false }); return { applied: false, consumedTool: false, resultType: 'nothing' }; }
    const targetName = resolveApplyTargetName(ctx, state, 'gear');
    const slot = normalizeEnchantSlot(info.slot);
    if (!enchantDefSupportsSlot(scrollDef, slot) || !affixSupportsSlot(resolvedAffixId, slot)) { ctx.cancel({ code: 'ENCHANT_INVALID_SLOT', message: `${targetName} cannot hold ${resolvedLabel}.`, consumesTurn: false }); return { applied: false, consumedTool: false, resultType: 'nothing' }; }
    const currentAffixes = Array.isArray(info.affixes) ? info.affixes.slice() : [];
    if (currentAffixes.includes(resolvedAffixId)) { ctx.cancel({ code: 'ENCHANT_ALREADY_PRESENT', message: `${targetName} already bears ${resolvedLabel}.`, consumesTurn: false }); return { applied: false, consumedTool: false, resultType: 'nothing' }; }
    ctx.helpers.patchItemInfo(targetId, { affixes: [...currentAffixes, resolvedAffixId] });
    ctx.helpers.attachEnchantment(targetId, { defId: `ench.${resolvedAffixId}`, affixId: resolvedAffixId, level: Math.max(1, Number(magnitude || 1) | 0), sourceKind: 'scroll', sourceId: Number(state?.toolId || 0) | 0, sourceKey: String(state?.toolIdentity || '') });
    ctx.io.emit('item:applied', { actor: state.actor, toolId: state.toolId, targetId, result: { type: 'gear_enchant', enchantType: resolvedType, affixId: resolvedAffixId, magnitude, proc, duration, metadata: { ...(metadata || {}) }, message: `You bind ${resolvedLabel} into ${targetName}.${resolvedDetail ? ` ${resolvedDetail}` : ''}` } });
    return { applied: true, consumedTool: true, resultType: `${resolvedType}_gear_enchant` };
  };
}

