export function isQuickChipActionable(it) {
  const t = String(it?.type || '');
  if (t === 'equip' || t === 'ammo' || t === 'wand') return true;
  if (t === 'tool') return true;
  if (isQuickChipPotion(it) || t === 'scroll' || t === 'learn' || t === 'book' || t === 'food' || t === 'gem') return (it?.count || 0) > 0;
  return false;
}

